fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    if len == 0 {
        return (Vec::new(), Vec::new());
    }
    
    // For arrays with length > 1, we need to split such that both parts
    // are strictly shorter than the original. The simplest approach is
    // to split at len/2, which ensures both parts are shorter when len > 1.
    let split_point = len / 2;
    
    // Ensure both parts are non-empty when len > 1
    // (if len == 1, we can't split into two non-empty parts that are both shorter)
    if len == 1 {
        // For a single element, we can return one empty and one with the element
        // This satisfies: concatenation reconstructs original, sum of lengths equals original,
        // and both returned arrays are shorter than original (empty array has length 0 < 1)
        return (Vec::new(), a);
    }
    
    // Split the vector into two parts
    let first = a[..split_point].to_vec();
    let second = a[split_point..].to_vec();
    
    (first, second)
}